function firebaseVerificationMessage(){return authText('Письмо подтверждения отправлено. Откройте ссылку в письме. Вход в этой вкладке выполнится автоматически. Проверьте также папку «Спам».','Verification email sent. Open the link in the email. This tab will sign you in automatically. Check your spam folder too.')}
