function checkVerification(){if(restoring){verificationTimer=setTimeout(checkVerification,500);return}if(verificationBusy||currentUser||authProvider!=='firebase')return;if(document.hidden){verificationTimer=setTimeout(checkVerification,10000);return}verificationBusy=true;var verificationEpoch=authEpoch;api('/api/firebase/verification-status',{method:'POST',body:{}}).then(function(result){if(verificationEpoch!==authEpoch||currentUser)return;if(result.authenticated){verificationWaiting=false;clearTimeout(verificationTimer);pendingPassword='';$('authPassword').value='';$('authPassword2').value='';$('firebaseVerifyNotice').hidden=true;acceptSession(result.user);return historyLoad.then(function(){hideAuth();afterLogin()})}verificationWaiting=!!result.pending;if(verificationWaiting)showFirebaseNotice(firebaseVerificationMessage())}).catch(function(error){if(error.status===401){verificationWaiting=false;return}if(verificationWaiting)setAuthError(error.message)}).finally(function(){verificationBusy=false;if(verificationWaiting&&!currentUser)verificationTimer=setTimeout(checkVerification,10000)})}
window.addEventListener('focus',function(){if(verificationWaiting){clearTimeout(verificationTimer);checkVerification()}});
