$('authBtn').onclick=function(){++authEpoch;
var btn=this,email=$('authEmail').value.trim(),pass=$('authPassword').value;
setAuthError('');
if(authProvider==='loading'){setAuthError(authText('Настройки сервера ещё загружаются.','Server settings are still loading.'));return}
if(!email||!pass){setAuthError(authText('Введите почту и пароль.','Enter email and password.'));return}
if(pass.length<(authMode==='register'?8:6)){setAuthError(authMode==='register'?authText('Пароль должен содержать минимум 8 символов.','Password must be at least 8 characters.'):authText('Введите пароль.','Enter your password.'));return}
if(authMode==='register'){
 if(pass!==$('authPassword2').value){setAuthError(authText('Пароли не совпадают.','Passwords do not match.'));return}
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){setAuthError(authText('Введите корректную почту.','Enter a valid email.'));return}
 btn.disabled=true;btn.textContent=authText('Отправляем…','Sending…');
 var request=authProvider==='firebase'?api('/api/firebase/register',{method:'POST',body:{email:email,password:pass,locale:settings.lang}}):api('/api/register/send-code',{method:'POST',body:{email:email}});
 request.then(function(){
  if(authProvider==='firebase'){pendingPassword='';$('authPassword').value='';$('authPassword2').value='';setAuthMode('login');showAuthStep('fields');showFirebaseNotice(firebaseVerificationMessage());startVerificationWatch();}
  else{pendingEmail=email;pendingPassword=pass;$('authCodeEmail').textContent=email;showAuthStep('code');$('authCode').value='';$('authCode').focus();startCodeTimer()}
 }).catch(function(e){setAuthError(e.message)}).finally(function(){btn.disabled=false;btn.textContent=authMode==='login'?authText('Войти','Sign in'):authText('Создать аккаунт','Create account')});
}else{
 btn.disabled=true;btn.textContent=authText('Входим…','Signing in…');
 api('/api/login',{method:'POST',body:{email:email,password:pass,deviceId:DEVICE_ID}})
 .then(function(d){pendingPassword='';$('authPassword').value='';$('authPassword2').value='';$('firebaseVerifyNotice').hidden=true;acceptSession(d.user);return historyLoad})
 .then(function(){hideAuth();afterLogin()})
 .catch(function(e){setAuthError(e.message);if(e.code==='EMAIL_NOT_VERIFIED'){startVerificationWatch();showFirebaseNotice(authText('Подтвердите почту по ссылке из письма. При необходимости запросите новое письмо кнопкой ниже.','Verify your email using the link. You can request another email below.'))}})
 .finally(function(){btn.disabled=false;btn.textContent=authText('Войти','Sign in')});
}
};
$('firebaseResendBtn').onclick=function(){var button=this,email=$('authEmail').value.trim(),password=$('authPassword').value;if(!email||!password){setAuthError(authText('Введите почту и пароль, затем нажмите «Отправить письмо повторно».','Enter email and password, then resend the verification email.'));return}button.disabled=true;setAuthError('');api('/api/firebase/resend-verification',{method:'POST',body:{email:email,password:password,locale:settings.lang}}).then(function(result){$('authPassword').value='';if(!result.alreadyVerified)startVerificationWatch();showFirebaseNotice(result.alreadyVerified?authText('Почта уже подтверждена. Введите пароль и войдите.','Email already verified. Enter your password and sign in.'):firebaseVerificationMessage())}).catch(function(e){setAuthError(e.message)}).finally(function(){button.disabled=false})};
$('authCodeResend').onclick=function(){fetch(API_URL+'/api/register/send-code',{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:pendingEmail})}).then(function(r){return r.json()}).then(function(j){if(j.error)setAuthError(localizedError(j.error,j.code));else startCodeTimer()})};
$('authCodeBtn').onclick=function(){
var btn=this,code=$('authCode').value.trim();
setAuthError('');
if(!code||code.length!==6){setAuthError(authText('Введите шестизначный код','Enter the 6-digit code'));return}
btn.disabled=true;btn.textContent=authText('Проверяем…','Verifying…');
api('/api/register',{method:'POST',body:{email:pendingEmail,password:pendingPassword,code:code,deviceId:DEVICE_ID}})
.then(function(d){pendingPassword='';$('authPassword').value='';$('authPassword2').value='';acceptSession(d.user);return historyLoad})
.then(function(){hideAuth();afterLogin()})
.catch(function(e){setAuthError(e.message)})
.finally(function(){btn.disabled=false;btn.textContent=t().confirm});
};

