function isSubActive(){return currentUser&&currentUser.subscription_until&&currentUser.subscription_until>Date.now()}
function updateUpgradeBtn(){if(isSubActive()){$('upgradeBtn').classList.add('active');$('upgradeLabel').textContent=t().plusActive}else{$('upgradeBtn').classList.remove('active');$('upgradeLabel').textContent=t().upgrade}}
function openSubscription(){payState={method:null,step:'card'};renderSub();openPanel($('subModal'))}
function closeSubscription(){closePanel($('subModal'))}
$('closeSub').onclick=closeSubscription;
$('subModal').onclick=function(e){if(e.target===this)closeSubscription()};
$('upgradeBtn').onclick=function(){if(isSubActive())return;openSubscription()};

function renderSub(){
var tt=t();var body=$('subBody');var isPlus=isSubActive();
var benefits=[tt.b1,tt.b2,tt.b3,tt.b4,tt.b5];
var bh=benefits.map(function(b){return '<li>'+esc(b)+'</li>'}).join('');
if(payState.step==='card'){
body.innerHTML='<div class="plan-card plus"><div class="plan-title">Pongy Plus</div><div style="font-size:12px;font-weight:600;color:var(--fg2);text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px">'+esc(tt.subBenefits)+'</div><ul class="plan-features">'+bh+'</ul><div class="plan-price">'+SUB_PRICE+' ₽ <span style="font-size:13px;color:var(--fg2);font-weight:500">/ '+esc(tt.month)+'</span></div><button class="plan-btn" id="buyBtn">'+(isPlus?''+esc(tt.extendPlus):''+esc(tt.buyPlus))+'</button></div>';
$('buyBtn').onclick=function(){payState.step='method';renderSub()};
}else if(payState.step==='method'){
body.innerHTML='<div class="field-label">'+esc(tt.payTitle)+'</div><div class="pay-methods"><button type="button" class="pay-method'+(payState.method==='sbp'?' selected':'')+'" data-method="sbp"><svg class="pay-icon-sbp" viewBox="0 0 48 48" fill="none"><circle cx="24" cy="24" r="20" stroke="currentColor" stroke-width="2.5"/><path d="M16 20h16M16 24h10M16 28h16M16 32h10" stroke="currentColor" stroke-width="2.5" stroke-linecap="round"/><circle cx="30" cy="24" r="3" fill="currentColor"/></svg><span>'+esc(tt.paySbp)+'</span></button><button type="button" class="pay-method'+(payState.method==='card'?' selected':'')+'" data-method="card"><svg class="pay-icon-card" viewBox="0 0 48 48" fill="none"><rect x="6" y="12" width="36" height="24" rx="4" stroke="currentColor" stroke-width="2.5"/><path d="M6 20h36" stroke="currentColor" stroke-width="2.5"/></svg><span>'+esc(tt.payCard)+'</span></button><button type="button" class="pay-method'+(payState.method==='ru'?' selected':'')+'" data-method="ru"><svg class="pay-icon-ru" viewBox="0 0 48 48" fill="none"><rect x="6" y="12" width="36" height="24" rx="4" stroke="currentColor" stroke-width="2.5"/><path d="M6 20h36" stroke="currentColor" stroke-width="2.5"/><rect x="10" y="6" width="28" height="6" rx="1" fill="#fff" stroke="currentColor" stroke-width="1"/><rect x="10" y="8" width="28" height="2" fill="#0039a6"/><rect x="10" y="10" width="28" height="2" fill="#d52b1e"/></svg><span>'+esc(tt.payCardRu)+'</span></button></div><button class="plan-btn" id="payNext" style="margin-top:16px;'+(payState.method?'':'opacity:.5;cursor:not-allowed')+'" '+(payState.method?'':'disabled')+'>'+esc(tt.payNext)+'</button><button class="pay-back" id="payBack">← '+esc(tt.payBack)+'</button>';

body.querySelectorAll('.pay-method').forEach(function(n){n.onclick=function(){payState.method=n.dataset.method;renderSub()}});
var nx=$('payNext');if(nx&&payState.method)nx.onclick=function(){payState.step='confirm';renderSub()};
$('payBack').onclick=function(){payState.step='card';renderSub()};
}else if(payState.step==='confirm'){
var methodName=payState.method==='sbp'?tt.paySbp:payState.method==='ru'?tt.payCardRu:tt.payCard;
body.innerHTML='<div class="field-label">'+esc(methodName)+'</div><p class="checkout-summary">Pongy Plus · '+SUB_PRICE+' ₽</p><p class="checkout-security">'+esc(authText('Реквизиты карты вводятся только на защищённой странице платёжного сервиса. QR-код создаётся сервисом для конкретного платежа.','Card details are entered only on the payment provider’s secure checkout. The provider creates a QR code for each payment.'))+'</p><button type="button" class="plan-btn" id="payConfirm">'+esc(tt.payConfirm)+'</button><button type="button" class="pay-back" id="payBack">← '+esc(tt.payBack)+'</button>';
$('payConfirm').onclick=function(){payState.step='unavailable';renderSub()};$('payBack').onclick=function(){payState.step='method';renderSub()};
}else if(payState.step==='unavailable'){body.innerHTML='<p class="payment-notice">'+esc(tt.payUnavailable)+'</p><button class="pay-back" id="payBack">← '+esc(tt.payBack)+'</button>';$('payBack').onclick=function(){payState.step='method';renderSub()};}
}

