box.innerHTML='<div style="padding:14px;border-radius:14px;background:linear-gradient(135deg,rgba(99,102,241,.15),rgba(139,92,246,.08));border:1px solid rgba(99,102,241,.4)"><div style="font-weight:700;color:var(--accent);font-size:15px;margin-bottom:8px">'+esc(authText('На данный момент у вас активен платный тариф','Your current plan is paid'))+'</div><div style="font-size:12.5px;color:var(--fg2);line-height:1.7">'+esc(authText('Доступность платных моделей зависит от их подключения на сайте.','Paid model access depends on the models enabled on this site.'))+'</div><div style="margin-top:10px;font-size:12.5px"><strong>'+esc(daysLabel(days))+'</strong></div></div>';
